import DefaultTheme from "vitepress/theme";
import type { Theme } from "vitepress";
import { theme, useOpenapi } from "vitepress-openapi/client";
import "vitepress-openapi/dist/style.css";
// Generated by scripts/build-openapi.mjs before vitepress dev/build (INT-302).
import spec from "../../public/openapi/public.v1.json" with { type: "json" };
// INT-403 — username/password token helper on /api/.
import ApiTokenHelper from "./ApiTokenHelper.vue";

export default {
  extends: DefaultTheme,
  async enhanceApp({ app }) {
    useOpenapi({
      spec,
      config: {
        // INT-303 — let operators paste their own gateway URL in the playground.
        server: {
          allowCustomServer: true,
        },
        // INT-407 — persistAuth stores vueuse Refs; deep-watch then misses token
        // edits so Try it out / curl samples ship without Authorization. Keep
        // plain-string auth values so the request rebuilds on input.
        // vitepress-openapi 0.2.12 prefixes `Bearer` for http schemes; ≥0.2.13
        // needs a newer VitePress (`useData` export) than our 1.6.x pin.
        storage: {
          persistAuth: false,
        },
      },
    });
    app.component("ApiTokenHelper", ApiTokenHelper);
    theme.enhanceApp({ app });
  },
} satisfies Theme;
